//#CTL2

function integer transform() {
    $out.0.email_id = $in.0.email_id;
    $out.0.from_address = $in.0.from_address;
    $out.0.subject = $in.0.subject;

    // Check if internal email - full string ends with @company.com
    // Using ?= to find the pattern anywhere (contains)
    $out.0.is_internal = nvl($in.0.from_address, "") ?= "(?i)@company\\.com$";

    // Check if urgent using  contains() function (search for substring)
    $out.0.is_urgent = contains(nvl($in.0.subject, ""), "URGENT");

    // Check for attachment references using ?= with alternation
    $out.0.has_attachment_ref = nvl($in.0.body, "") ?= "(?i)attach(ment|ed)";

    return ALL;
}

// Note:
// - ?= is regex contains (pattern found anywhere in string)
// - contains() is a function searching for literal substring
// - ~= is regex full match (entire string must match)
