//#CTL2

function integer transform() {
    $out.0.filename = $in.0.filename;

    // Classify by extension using ~= regex full match (case-insensitive)
    $out.0.is_image = nvl($in.0.filename, "") ~= "(?i).*\\.(jpg|jpeg|png|gif|bmp|svg)";
    $out.0.is_document = nvl($in.0.filename, "") ~= "(?i).*\\.(doc|docx|pdf|txt|xls|xlsx)";
    $out.0.is_archive = nvl($in.0.filename, "") ~= "(?i).*\\.(zip|tar|gz|rar|7z)";

    // Check for temp folder using .in. literal contains
    $out.0.is_in_temp = contains(nvl($in.0.path, ""),"/temp/") || contains(nvl($in.0.path, ""),"\\temp\\");

    return ALL;
}

// Note:
// - ~= matches entire filename, so .* prefix needed to match any name before extension
// - Handle both Unix (/) and Windows (\) path separators
