function decimal jsonNumberToDecimal(variant raw) {
    if (isnull(raw)) {
        return null;
    }
    if (raw typeof integer) {
        return cast(raw, integer);
    }
    if (raw typeof long) {
        return cast(raw, long);
    }
    if (raw typeof number) {
        return cast(raw, number);
    }
    if (raw typeof string) {
        return str2decimal(cast(raw, string));
    }
    return null;
}

function integer transform() {
    $out.0.id = $in.0.id;

    variant jsonData = parseJson(nvl($in.0.json_payload, ""));

    $out.0.name = cast(jsonData["name"], string) : null;
    $out.0.value = jsonNumberToDecimal(jsonData["value"]);
    $out.0.active = cast(jsonData["active"], boolean) : null;

    return ALL;
}
