//#CTL2

string[] day_names = ["Mon","Tue","Wed","Thu","Fri","Sat","Sun"];

function integer transform() {
    $out.0.event_id = $in.0.event_id;
    $out.0.event_type = $in.0.event_type;

    if (isnull($in.0.event_timestamp)) {
        $out.0.event_year = null;
        $out.0.event_month = null;
        $out.0.event_day = null;
        $out.0.day_of_week = null;
        $out.0.day_of_week_name = null;
        $out.0.is_weekend = null;
        return ALL;
    }

    // Extract date components using getter functions
    $out.0.event_year = getYear($in.0.event_timestamp);
    $out.0.event_month = getMonth($in.0.event_timestamp);
    $out.0.event_day = getDay($in.0.event_timestamp);

    // getDayOfWeek returns: 1 = Monday, ..., 6 = Saturday, 7 = Sunday
    integer dow = getDayOfWeek($in.0.event_timestamp);
    $out.0.day_of_week = dow;
    $out.0.day_of_week_name = day_names[dow-1]; // pick day's name from list of names, indexed from 0

    // Weekend is Saturday (6) or Sunday (7)
    $out.0.is_weekend = (dow == 6 || dow == 7);

    return ALL;
}

// Note: Use getYear(), getMonth(), getDay(), getDayOfWeek() to extract date parts.
// getDayOfWeek() returns 1 for Monday, ..., 7 for Sunday.
