//#CTL2

function string maskSSN(string ssn) {
    if (isEmpty(ssn)) {
        return "";
    }
    string digitsOnly = replace(ssn, "[^0-9]", "");
    if (length(digitsOnly) < 4) {
        return "XXX-XX-XXXX";
    }
    string last4 = right(digitsOnly, 4);
    return "XXX-XX-" + last4;
}

function string maskCreditCard(string cc) {
    if (isEmpty(cc)) {
        return "";
    }
    string digitsOnly = replace(cc, "[^0-9]", "");
    if (length(digitsOnly) < 4) {
        return "****-****-****-****";
    }
    string last4 = right(digitsOnly, 4);
    return "****-****-****-" + last4;
}

function string maskEmail(string email) {
    if (isnull(email) || isEmpty(email)) {
        return "";
    }
    integer atPos = indexOf(email, "@");
    if (atPos < 0) {
        return "****@****";
    }
    string firstChar = left(email, 1);
    string domain = substring(email, atPos);
    return firstChar + "***" + domain;
}

function integer transform() {
    $out.0.person_id = $in.0.person_id;
    $out.0.ssn_masked = maskSSN($in.0.ssn);
    $out.0.cc_masked = maskCreditCard($in.0.credit_card);
    $out.0.email_masked = maskEmail($in.0.email);
    return ALL;
}
