//#CTL2

function integer transform() {
    $out.0.contact_id = $in.0.contact_id;

    // Extract only digits
    string digits = replace(nvl($in.0.phone_raw, ""), "[^0-9]", "");
    $out.0.phone_digits = digits;

    // Handle 11 digits starting with 1 (country code)
    if (length(digits) == 11 && left(digits, 1) == "1") {
        digits = substring(digits, 1);
    }

    // Validate and format
    if (length(digits) == 10) {
        $out.0.is_valid = true;
        string area = substring(digits, 0, 3);
        string exchange = substring(digits, 3, 3);
        string subscriber = substring(digits, 6, 4);
        $out.0.phone_formatted = "(" + area + ") " + exchange + "-" + subscriber;
    } else {
        $out.0.is_valid = false;
        $out.0.phone_formatted = nvl($in.0.phone_raw, "");
    }

    return ALL;
}
