integer orderCount;
decimal totalSpent;
date firstOrder;
date lastOrder;
map[string, integer] categoryCount;

function integer append() {
    orderCount = orderCount + 1;
    totalSpent = totalSpent + nvl($in.0.order_amount, 0D);

    // Track dates
    if (!isnull($in.0.order_date) && (firstOrder == null || $in.0.order_date < firstOrder)) {
        firstOrder = $in.0.order_date;
    }
    if (!isnull($in.0.order_date) && (lastOrder == null || $in.0.order_date > lastOrder)) {
        lastOrder = $in.0.order_date;
    }

    // Count categories
    string cat = nvl($in.0.product_category, "");
    if (isnull(categoryCount[cat])) {
        categoryCount[cat] = 0;
    }
    categoryCount[cat] = categoryCount[cat] + 1;

    return OK;
}

function string findTopCategory() {
    string[] keys = getKeys(categoryCount);
    string topCat = "";
    integer maxCount = 0;

    for (integer i = 0; i < length(keys); i++) {
        string cat = keys[i];
        integer cnt = categoryCount[cat];
        if (cnt > maxCount) {
            maxCount = cnt;
            topCat = cat;
        }
    }
    return topCat;
}


function integer transform() {
    $out.0.customer_id = $in.0.customer_id;
    $out.0.total_orders = orderCount;
    $out.0.total_spent = totalSpent;
    $out.0.first_order = firstOrder;
    $out.0.last_order = lastOrder;
    $out.0.favorite_category = findTopCategory();
    return ALL;
}

function void clean() {
    orderCount = 0;
    totalSpent = 0D;
    firstOrder = null;
    lastOrder = null;
    categoryCount = {};
}

//Note: in CTL2 function has to be defined before used
