//#CTL2

integer gid;
string summary;
integer cnt;

function integer append() {
    if (cnt == 0) {
        gid = $in.0.group_id;
        summary = "";
    }
    summary = nvl(summary, "") + "[" + nvl($in.0.value, "") + "]";
    cnt++;
    return OK;
}

function integer transform() {
    // Simulate an occasional failure
    if (length(nvl(summary, "")) > 1000) {
        // throw by calling a failing operation
        charAt("", 1);
    }

    $out.0.group_id = gid;
    $out.0.summary = summary;
    $out.0.error = null;
    return OK;
}

function integer transformOnError(string errorMessage, string stackTrace) {
    $out.0.group_id = gid;
    $out.0.summary = nvl(summary, "");
    $out.0.error = errorMessage;
    return OK;
}

function void clean() {
    gid = 0;
    summary = "";
    cnt = 0;
}
