//#CTL2

integer cnt;
decimal total;
decimal maxVal;
date earliest;
string concatNames;

function integer append() {
    cnt++;
    // Compute line amount as quantity * unit_price; guard unit_price null with nvl()
    decimal lineAmount = $in.0.quantity * nvl($in.0.unit_price, 0D);
    total += lineAmount;

    // Guard max comparison against null via nvl() in lineAmount above
    maxVal = (cnt == 1 || lineAmount > maxVal) ? lineAmount : maxVal;

    // Earliest order_date: comparison guarded so '<' never sees null
    if (isnull(earliest) || (!isnull($in.0.order_date) && $in.0.order_date < earliest)) {
        earliest = $in.0.order_date;
    }

    string nm = nvl($in.0.status, "");
    if (!isBlank(nm)) {
        // Append comma only when concatNames already has content
        concatNames += (isBlank(concatNames) ? "" : ",") + nm;
    }
    return OK;
}

function integer transform() {
    $out.0.order_id = $in.0.order_id;
    $out.0.count = cnt;
    $out.0.total_amount = total;
    $out.0.max_amount = maxVal;
    $out.0.earliest_date = earliest;
    $out.0.avg_amount = (cnt > 0) ? roundHalfToEven(total / cnt, 2) : 0D;
    $out.0.names = concatNames;
    return OK;
