    // Initialize accumulator only when timestamp is present; otherwise keep nulls.
    if (!isnull($in.0.log_timestamp)) {
        groupAccumulator.first_timestamp = $in.0.log_timestamp;
        groupAccumulator.last_timestamp = $in.0.log_timestamp;
    } else {
        groupAccumulator.first_timestamp = null;
        groupAccumulator.last_timestamp = null;
    }
    groupAccumulator.action_count = 1;
    return;
}

function boolean updateGroup(SessionAccumulator groupAccumulator) {
    // Track first and last timestamps (ordering comparisons throw if either operand is null)
    if (!isnull($in.0.log_timestamp)) {
        if (isnull(groupAccumulator.first_timestamp) || $in.0.log_timestamp < groupAccumulator.first_timestamp) {
            groupAccumulator.first_timestamp = $in.0.log_timestamp;
