        if (isnull(groupAccumulator.last_timestamp) || $in.0.log_timestamp > groupAccumulator.last_timestamp) {
            groupAccumulator.last_timestamp = $in.0.log_timestamp;
        }
    }

    groupAccumulator.action_count = groupAccumulator.action_count + 1;
    return true;
