// Rollup component CTL2

function void initGroup(ClaimAccumulator groupAccumulator) {
    // Initialize accumulator fields for a new policy_id group
    groupAccumulator.num_claims = 0;
    groupAccumulator.total_claimed = 0D;
    groupAccumulator.approved_total = 0D;
    groupAccumulator.rejected_count = 0;
    groupAccumulator.latest_claim_date = null;
    return;
}

function boolean updateGroup(ClaimAccumulator groupAccumulator) {
    // Increment claim count
    groupAccumulator.num_claims = groupAccumulator.num_claims + 1;

    // Safely add claim amount (nullable input -> treat null as 0D)
    groupAccumulator.total_claimed =
        groupAccumulator.total_claimed + nvl($in.0.claim_amount, 0D);

    // Track approved and rejected separately based on status
    if ($in.0.claim_status == "APPROVED") {
        groupAccumulator.approved_total =
            groupAccumulator.approved_total + nvl($in.0.claim_amount, 0D);
    } else if ($in.0.claim_status == "DENIED") {
        groupAccumulator.rejected_count = groupAccumulator.rejected_count + 1;
    }

    // Track latest (maximum) claim_date, guarding against nulls
    if (isnull(groupAccumulator.latest_claim_date)) {
        // First non-null date encountered becomes the latest
        if (!isnull($in.0.claim_date)) {
            groupAccumulator.latest_claim_date = $in.0.claim_date;
        }
    } else {
        // Both sides must be non-null before using '>' comparison
        if (!isnull($in.0.claim_date)
            && $in.0.claim_date > groupAccumulator.latest_claim_date) {
            groupAccumulator.latest_claim_date = $in.0.claim_date;
        }
    }

    return true;
}

function boolean finishGroup(ClaimAccumulator groupAccumulator) {
    // Nothing special to do at the end of the group
    return true;
}

function integer updateTransform(integer counter, ClaimAccumulator groupAccumulator) {
    return SKIP;
}

function integer transform(integer counter, ClaimAccumulator groupAccumulator) {
    // Emit exactly one summary record per policy group (on the first call)
    if (counter > 0) {
        return SKIP;
    }

    // Map to output metadata
    $out.0.policy_id = $in.0.policy_id;
    $out.0.num_claims = groupAccumulator.num_claims;
    $out.0.total_claimed = groupAccumulator.total_claimed;

    // Compute average claim safely; avoid division by zero
    if (groupAccumulator.num_claims > 0) {
        $out.0.avg_claim =
            nvl(groupAccumulator.total_claimed, 0D)
            / groupAccumulator.num_claims;
    } else {
        $out.0.avg_claim = 0D;
    }

    $out.0.approved_total = groupAccumulator.approved_total;
    $out.0.rejected_count = groupAccumulator.rejected_count;
    $out.0.latest_claim_date = groupAccumulator.latest_claim_date;

    return ALL;
}
