The required logic can be implemented using a **Rollup** component with group key `product_code;txn_date` and group accumulator metadata `SalesAggAcc` as described.

```ctl
//#CTL2

function void initGroup(SalesAggAcc groupAccumulator) {
    groupAccumulator.total_units = 0L;
    groupAccumulator.gross_amount = 0D;
    groupAccumulator.discounted_amount = 0D;
    groupAccumulator.txn_count = 0;
    return;
}

function boolean updateGroup(SalesAggAcc groupAccumulator) {
    long units = long2integer(nvl($in.0.units_sold, 0)) : 0L;
    decimal unit_price = nvl($in.0.unit_price, 0D);

    decimal line_gross = units * unit_price;
    decimal effective_discount = nvl($in.0.discount_pct, 0D) / 100D;
    decimal line_discounted = line_gross * (1D - effective_discount);

    groupAccumulator.total_units += units;
    groupAccumulator.gross_amount += line_gross;
    groupAccumulator.discounted_amount += line_discounted;
    groupAccumulator.txn_count++;

    return true;
}

function boolean finishGroup(SalesAggAcc groupAccumulator) {
    return true;
}

function integer updateTransform(integer counter, SalesAggAcc groupAccumulator) {
    return SKIP;
}

function integer transform(integer counter, SalesAggAcc groupAccumulator) {
    if (counter > 0) {
        return SKIP;
    }

    $out.0.product_code = $in.0.product_code;
    $out.0.txn_date = $in.0.txn_date;

    $out.0.total_units = groupAccumulator.total_units;
    $out.0.txn_count = groupAccumulator.txn_count;
    $out.0.total_revenue = groupAccumulator.gross_amount;
    $out.0.total_discounted_revenue = groupAccumulator.discounted_amount;

    if (!isnull(groupAccumulator.total_units) && groupAccumulator.total_units != 0L) {
        $out.0.avg_unit_price = groupAccumulator.gross_amount / groupAccumulator.total_units;
    } else {
        $out.0.avg_unit_price = 0D;
    }

    // first non-null channel in the group; may remain null
    string primary_channel = null;
    SalesTxn rec = lookup(SalesTxn).get($in.0.product_code, $in.0.txn_date);
    while (!isnull(rec) && isnull(primary_channel)) {
        if (!isnull(rec.channel)) {
            primary_channel = rec.channel;
        }
        rec = lookup(SalesTxn).next();
    }
    $out.0.primary_channel = primary_channel;

    return OK;
}
```

