function void initGroup(MerchantDailyAcc groupAccumulator) {
    groupAccumulator.total_tx_count = 0;
    groupAccumulator.total_gross = 0D;
    groupAccumulator.total_fees = 0D;
    groupAccumulator.refund_tx_count = 0;
