function boolean updateGroup(MerchantDailyAcc groupAccumulator) {
    groupAccumulator.total_tx_count = groupAccumulator.total_tx_count + 1;

    groupAccumulator.total_gross = groupAccumulator.total_gross + nvl($in.0.gross_amount, 0D);

    // fee_amount is nullable on input
    groupAccumulator.total_fees =
        groupAccumulator.total_fees + nvl($in.0.fee_amount, 0D);

    if ($in.0.refund_flag == "Y") {
        groupAccumulator.refund_tx_count = groupAccumulator.refund_tx_count + 1;
